reference_solution:
def every_integer_is_covered(ranges, left, right):
    difference = [0] * 52
    for start, end in ranges:
        difference[start] += 1
        difference[end + 1] -= 1
    active = 0
    for value in range(1, 51):
        active += difference[value]
        if left <= value <= right and active == 0:
            return False
    return True

